html:
{% set is_tax = doc.invoice_type == "Tax Invoice" %}
<style>
  @page { size: A4; margin: 8mm; }
  body { margin: 0; padding: 0; font-family: Arial, sans-serif; color: #000; }
  .ti-page { width: 100%; box-sizing: border-box; font-family: Arial, sans-serif; color: #000; font-size: 12px; border: 1px solid #ccc; padding: 6mm; }

  .ti-header { width: 100%; border-collapse: collapse; margin-bottom: 6px; }
  .ti-header td { vertical-align: top; border: none; }
  .ti-logo-cell { width: 80px; }
  .ti-logo-cell img { width: 68px; height: 58px; object-fit: contain; display: block; }
  .ti-company-cell { padding-left: 8px; }
  .ti-company-name { font-size: 17px; font-weight: 700; }
  .ti-company-trn { font-size: 12px; margin-top: 2px; }
  .ti-doc-title { text-align: right; font-size: 24px; font-weight: 400; color: #333; vertical-align: middle; }

  .ti-divider { border-top: 1px solid #000; margin: 4px 0 8px; }

  .ti-info-strip { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
  .ti-info-strip td { border: none; padding: 1px 0; font-size: 12px; vertical-align: top; }
  .ti-info-label { color: #333; padding-right: 4px; white-space: nowrap; }
  .ti-info-value { font-weight: 700; }
  .ti-info-left { width: 60%; }
  .ti-info-right { width: 40%; }

  .ti-party-table { width: 100%; border-collapse: collapse; margin-bottom: 10px; table-layout: fixed; }
  .ti-party-table td { border: 1px solid #999; vertical-align: top; padding: 0; }
  .ti-party-head { background: #f0f0f0; font-weight: 700; padding: 3px 6px; border-bottom: 1px solid #999; font-size: 12px; }
  .ti-party-body { padding: 6px 6px 10px; font-size: 12px; }
  .ti-party-name { font-weight: 700; }

  .ti-goods { width: 100%; border-collapse: collapse; table-layout: fixed; margin-bottom: 0; }
  .ti-goods th, .ti-goods td { border: 1px solid #999; padding: 5px 6px; font-size: 11px; line-height: 1.3; }
  .ti-goods th { background: #f0f0f0; font-weight: 700; text-align: center; }
  .ti-goods td.center { text-align: center; }
  .ti-goods td.right { text-align: right; }
  .ti-subtotal-row td { font-weight: 700; border: 1px solid #999; }

  .ti-bottom { width: 100%; border-collapse: collapse; margin-top: 10px; table-layout: fixed; }
  .ti-bottom td { border: none; vertical-align: top; padding: 0; }
  .ti-bottom-left { width: 58%; padding-right: 10px; font-size: 11px; }
  .ti-bottom-right { width: 42%; }

  .ti-words-label { font-size: 11px; }
  .ti-words-value { font-weight: 700; font-style: italic; font-size: 12px; margin-bottom: 8px; }

  .ti-terms-title { font-weight: 700; margin-top: 6px; }
  .ti-terms ol { margin: 2px 0 8px 16px; padding: 0; }
  .ti-declaration { margin-bottom: 8px; }

  .ti-bank-title { font-weight: 700; margin-bottom: 2px; }
  .ti-bank-line { margin-bottom: 4px; }

  .ti-balance-box { border: 1px solid #999; padding: 6px 8px; display: flex; justify-content: space-between; font-weight: 700; font-size: 13px; margin-bottom: 12px; }

  .ti-sign-block { text-align: center; }
  .ti-sign-company { font-weight: 700; font-size: 12px; margin-bottom: 4px; }
  .ti-stamp-area { height: 90px; display: flex; align-items: center; justify-content: center; }
  .ti-stamp-area img { max-width: 100px; max-height: 90px; object-fit: contain; opacity: 0.9; }
  .ti-sign-title { font-size: 11px; margin-top: 4px; }

  .ti-footer { text-align: center; font-size: 10px; color: #555; margin-top: 10px; border-top: 1px solid #ccc; padding-top: 4px; }

  @media print { .ti-page { page-break-after: avoid; } }
</style>

<div class="ti-page">

  <table class="ti-header">
    <tr>
      <td class="ti-logo-cell">
        <img src="/files/AP_Logo.webp" alt="Company Logo" onerror="this.style.display='none'">
      </td>
      <td class="ti-company-cell">
        <div class="ti-company-name">Asia Petrochemicals LLC OPC</div>
        {% if is_tax %}<div class="ti-company-trn">TRN {{ frappe.db.get_value("Company", frappe.db.get_default("company"), "tax_id") or "100283348900003" }}</div>{% endif %}
      </td>
      <td class="ti-doc-title">{{ doc.invoice_type or "Tax Invoice" }}</td>
    </tr>
  </table>

  <div class="ti-divider"></div>

  <table class="ti-info-strip">
    <tr>
      <td class="ti-info-left">
        <table style="width:100%; border-collapse:collapse;">
          <tr><td class="ti-info-label" style="width:130px;">Invoice#</td><td>: <span class="ti-info-value">{{ doc.name }}</span></td></tr>
          <tr><td class="ti-info-label">Invoice Date</td><td>: <span class="ti-info-value">{{ frappe.utils.formatdate(doc.invoice_date) }}</span></td></tr>
          <tr><td class="ti-info-label">Terms of Payment</td><td>: <span class="ti-info-value">{{ doc.mode_of_payment or "-" }}</span></td></tr>
          <tr><td class="ti-info-label">Due Date</td><td>: <span class="ti-info-value">-</span></td></tr>
        </table>
      </td>
      <td class="ti-info-right">
        <table style="width:100%; border-collapse:collapse;">
          <tr><td class="ti-info-label" style="width:150px;">Shipment Incoterms</td><td>: <span class="ti-info-value">{{ doc.terms_of_delivery or "-" }}</span></td></tr>
        </table>
      </td>
    </tr>
  </table>

  <table class="ti-party-table">
    <tr>
      <td style="width:50%;">
        <div class="ti-party-head">Bill To</div>
        <div class="ti-party-body">
          <div class="ti-party-name">{{ doc.buyer_name or "-" }}</div>
          <div>{{ doc.buyer_address or "" }}</div>
        </div>
      </td>
      <td style="width:50%;">
        <div class="ti-party-head">Ship To (Address)</div>
        <div class="ti-party-body">
          <div class="ti-party-name">{{ doc.consignee_name or doc.buyer_name or "-" }}</div>
          <div>{{ doc.consignee_address or doc.buyer_address or "" }}</div>
        </div>
      </td>
    </tr>
  </table>

  <table class="ti-goods">
    <thead>
      <tr>
        <th style="width:4%;">S No.</th>
        <th style="width:26%;">Item &amp; Description</th>
        <th style="width:9%;">Qty</th>
        <th style="width:11%;">Unit Price</th>
        <th style="width:11%;">Amount</th>
        <th style="width:12%;">Taxable Amount</th>
        <th style="width:7%;">Tax %</th>
        <th style="width:10%;">Tax Amount</th>
        <th style="width:10%;">Total Incl. VAT</th>
      </tr>
    </thead>
    <tbody>
      {% for row in (doc.items or []) %}
      <tr>
        <td class="center">{{ loop.index }}</td>
        <td>
          {{ (row.description or row.item_name or row.item or "-").split("\n")[0] }}
        </td>
        <td class="center">{{ row.quantity }} {{ row.uom or "" }}</td>
        <td class="right">{{ "%.2f"|format(row.rate or 0) }}</td>
        <td class="right">{{ "%.2f"|format(row.amount or 0) }}</td>
        <td class="right">{{ "%.2f"|format(row.taxable_value or 0) }}</td>
        <td class="center">{{ "%.2f"|format(row.vat_percentage or 0) }} %</td>
        <td class="right">{{ "%.2f"|format(row.vat_amount or 0) }}</td>
        <td class="right">{{ "%.2f"|format(row.total_incl_vat or 0) }}</td>
      </tr>
      {% endfor %}
      <tr class="ti-subtotal-row">
        <td colspan="4" class="right">Sub Total</td>
        <td class="right">{{ "%.2f"|format(doc.taxable_value or 0) }}</td>
        <td class="right">{{ "%.2f"|format(doc.taxable_value or 0) }}</td>
        <td></td>
        <td class="right">{{ "%.2f"|format(doc.vat_amount or 0) }}</td>
        <td class="right">{{ "%.2f"|format(doc.grand_total or 0) }}</td>
      </tr>
    </tbody>
  </table>

  <table class="ti-bottom">
    <tr>
      <td class="ti-bottom-left">
        <div class="ti-words-label">Total In Words</div>
        <div class="ti-words-value">{{ doc.amount_in_words or "-" }}</div>

        <div class="ti-terms-title">Other terms and conditions :</div>
        <div class="ti-terms">
          <ol>
            <li>Documents to be submitted are the invoice, packing list, delivery note etc</li>
            <li>Price quoted above are on delivered basis</li>
          </ol>
        </div>
        <div class="ti-declaration">Declaration: We declare that this invoice shows the actual price of the goods described and that all particulars are true and correct.</div>

        <div class="ti-bank-title">Beneficiary: Asia Petrochemicals LLC OPC</div>
        <div class="ti-bank-line">1)-Bank Name: EMIRATES ISLAMIC BANK, Branch: EI HEALTH CARE CITY, Currency: USD, IBAN: AE780340003707529652701, Swift Code: MEBLAEAD</div>
        <div class="ti-bank-line">2)-Bank Name: Habib Bank AG Zurich, Branch: Main Branch-Dubai, Currency: USD, IBAN: AE420290120311333751440, Swift Code: HBZUAEADXXX</div>
        <div class="ti-bank-line">3)-Bank Name: Commercial Bank Dubai, Branch: Dubai, Currency: USD, A/C IBAN: AE600230000001005833726, CBD Swift Code: CBDUAEAD</div>
        <div class="ti-bank-line">4)-Bank Name: Habib Bank AG Zurich, Branch: Dubai Main Branch, Currency: EURO, IBAN: AE020290120311974751440</div>
      </td>
      <td class="ti-bottom-right">
        <div class="ti-balance-box"><span>Balance Due</span><span>AED {{ "%.2f"|format(doc.grand_total or 0) }}</span></div>

        <div class="ti-sign-block">
          <div class="ti-sign-company">Asia Petrochemicals LLC OPC</div>
          <div class="ti-stamp-area">
            <img src="/files/AP_Logo.webp" alt="Company Stamp" onerror="this.style.display='none'">
          </div>
          <div class="ti-sign-title">Authorized Signature</div>
        </div>
      </td>
    </tr>
  </table>

  <div class="ti-footer">
    Asia Petrochemicals LLC OPC, Plot # A 23 B, Al Jazeera Industrial Area, PO Box 76283, Ras al-Khaimah, United Arab Emirates &nbsp; 04-2384533 &nbsp; https://asia-petrochem.com
  </div>

</div>
